#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Walks through README "Setup (once)", plus the optional extras.
# Run it from a clone: ./scripts/setup-wizard.sh. With no origin remote, it creates
# the public repo. Safe to re-run: stages check GitHub first where they can.
# Nothing goes to .env: no local code reads these values, and .env isn't in .gitignore.

# Stage helpers. gh calls use GH_REPO, which stage 1 sets.
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
run() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }

has_secret() {
  local names
  names=$(gh secret list --json name --jq '.[].name' 2>/dev/null) || return 1
  grep -qx "$1" <<< "$names"
}

has_labels() {
  local names label
  names=$(gh label list --limit 100 --json name --jq '.[].name' 2>/dev/null) || return 1
  for label in idea grilled backlog reviewed done needs-human; do
    grep -qx "$label" <<< "$names" || return 1
  done
}

has_ruleset() {
  local names
  names=$(gh api "repos/{owner}/{repo}/rulesets" --jq '.[].name' 2>/dev/null) || return 1
  grep -qx master <<< "$names"
}

is_public()      { [[ "$(gh repo view "$REPO" --json visibility --jq .visibility)" == PUBLIC ]]; }
gh_pages_ready() { gh api "repos/{owner}/{repo}/branches/gh-pages" --silent 2>/dev/null; }
pages_ok()       { [[ "$(gh api "repos/{owner}/{repo}/pages" --jq .source.branch 2>/dev/null)" == gh-pages ]]; }

# key_status HEADER KEY sends "HEADER KEY" on a token-free API call and prints
# "<HTTP status> <the API's error message, if any>". The key goes in on stdin,
# so it never shows up in the process list.
key_status() {
  local out
  out=$(printf '%s %s\n' "$1" "$2" |
    curl -s -w '\n%{http_code}' -H @- -H 'anthropic-version: 2023-06-01' \
      https://api.anthropic.com/v1/models) || true
  printf '%s %s' "${out##*$'\n'}" \
    "$(sed -nE 's/.*"message":"(([^"\\]|\\.)*)".*/\1/p' <<< "${out%$'\n'*}" | sed 's/\\"/"/g')"
}

pages_by_hand() {
  open_url "https://github.com/$REPO/settings/pages"
  step "Under Build and deployment, set Source to 'Deploy from a branch'."
  step "Branch: gh-pages, folder / (root). Click Save."
  pause "Press Enter once it's saved"
}

# verify "what" "fix" cmd...: ✓ if cmd succeeds, else warn and add the fix to the to-do list.
verify() {
  local what="$1" fix="$2"; shift 2
  if "$@" >/dev/null 2>&1; then ok "$what"; else warn "$what: not yet"; SKIPPED+=("$fix"); fi
}

run_wizard() {

TOTAL_STAGES=11
cd "$(dirname "$0")/.."

banner "snapcap-agentic-poc: repo setup"

# ── 1. README step 1: a public GitHub repo with this folder pushed ────────
stage "GitHub CLI and repo"
say "The wizard talks to GitHub through gh, so gh has to be installed and signed in."
if ! command -v gh >/dev/null 2>&1; then
  warn "gh isn't installed."
  open_url "https://cli.github.com/"
  say "Install it (on macOS: brew install gh), then run this wizard again."
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  say "gh isn't signed in yet. Pick GitHub.com and follow gh's prompts."
  run gh auth login
fi
ok "gh is signed in as $(gh api user --jq .login)."

if ! REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null); then
  if origin=$(git remote get-url origin 2>/dev/null); then
    warn "origin points to $origin, but gh can't open that repo."
    say "Create it on GitHub as a public repo, or fix the remote, then run this wizard again."
    exit 1
  fi
  say "This folder has no GitHub repo yet. It needs a public one: on a free plan,"
  say "GitHub Pages and rulesets work only on public repos."
  ask REPO_NAME "Repo name, or org/name [$(basename "$PWD")]:"
  REPO_NAME=${REPO_NAME:-$(basename "$PWD")}
  confirm "Create the public repo $REPO_NAME and push this folder to it?" ||
    { warn "The rest needs a GitHub repo, so stopping here."; exit 1; }
  run gh repo create "$REPO_NAME" --public --source . --remote origin --push
  REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
fi
export GH_REPO="$REPO"

VISIBILITY=$(gh repo view "$REPO" --json visibility --jq .visibility)
BRANCH=$(gh repo view "$REPO" --json defaultBranchRef --jq .defaultBranchRef.name)
PERMISSION=$(gh repo view "$REPO" --json viewerPermission --jq .viewerPermission)
if [[ "$VISIBILITY" != PUBLIC ]]; then
  warn "$REPO is $VISIBILITY. On a free plan, Pages and rulesets need a public repo."
  if confirm "Make $REPO public? Anyone will then see its code, issues and Actions logs."; then
    run gh repo edit "$REPO" --visibility public --accept-visibility-change-consequences
  fi
fi
[[ "$PERMISSION" == ADMIN ]] ||
  warn "You're not an admin of $REPO ($PERMISSION). The ruleset and Pages stages need an admin."
[[ "$BRANCH" == master ]] ||
  warn "The default branch is $BRANCH, but the workflows and the ruleset expect master."

git fetch --quiet origin "$BRANCH" 2>/dev/null || true
if ! git merge-base --is-ancestor HEAD "origin/$BRANCH" 2>/dev/null; then
  warn "This checkout has commits that aren't on origin/$BRANCH. The agents run what's on GitHub."
  if [[ "$(git rev-parse --abbrev-ref HEAD)" == "$BRANCH" ]] && confirm "Push $BRANCH to origin now?"; then
    run git push origin "$BRANCH" || {
      warn "The push failed. Once the master ruleset is on, changes go through a PR."
      SKIPPED+=("Get your local commits onto origin/$BRANCH")
    }
  else
    SKIPPED+=("Get your local commits onto origin/$BRANCH")
  fi
fi
ok "Repo: https://github.com/$REPO ($BRANCH)"
pause "Press Enter to continue"

# ── 2. README step 2: the Claude GitHub App ───────────────────────────────
stage "Claude GitHub App"
say "Agents act as claude[bot] through this app's token. That's what lets one agent's"
say "label or PR start the next workflow: events made with GITHUB_TOKEN start nothing."
open_url "https://github.com/apps/claude"
step "Click Install (or Configure, if you've installed it before)."
step "Pick the account that owns the repo: ${REPO%%/*}."
step "Choose 'Only select repositories', select ${REPO#*/}, then Install (or Save)."
step "Accept the permissions the app asks for."
note "gh can't see app installs, so the Check stage asks you to confirm it."
pause "Press Enter once the app is installed on $REPO"

# ── 3. README step 3, part 1: a workspace with a spend limit ──────────────
stage "Claude Console: workspace and spend limit"
say "Agent runs are billed per token. The Default Workspace can't have a spend limit,"
say "so give this repo its own workspace and cap that."
note "Creating a workspace needs the admin role in your Console organization."
open_url "https://platform.claude.com/settings/workspaces/new"
step "Name it ${REPO#*/}, pick a color, and click Create workspace."
step "On the Workspaces page, select the new workspace."
step "In the panel that opens, click Spend limits and set a monthly cap (an alert too, if you like)."
note "Already made it on an earlier run? Just check that its spend limit is set."
pause "Press Enter once the workspace has a spend limit"

# ── 4. README step 3, part 2: the API key, as the ANTHROPIC_API_KEY secret
stage "Claude Console: API key"
say "The agent workflows read the Claude API key from the repo secret ANTHROPIC_API_KEY."
if has_secret ANTHROPIC_API_KEY && ! confirm "ANTHROPIC_API_KEY is already set on $REPO. Replace it?"; then
  ok "Keeping the current ANTHROPIC_API_KEY."
else
  open_url "https://platform.claude.com/settings/keys"
  step "Click Create key and name it '${REPO#*/} GitHub Actions'."
  step "Expiration is up to you. When it expires, re-run this wizard to put in a new key."
  step "Linked account: yourself, or a service account if your org has one for CI."
  step "Workspace: ${REPO#*/}. Unscoped keys fail here: the workflows send no workspace ID."
  step "Create the key and copy it (it starts with sk-ant-)."
  while true; do
    ask_secret ANTHROPIC_API_KEY "Paste the key, then press Enter:"
    # Drop whitespace and the bracketed-paste markers some terminals wrap a paste in
    key=${ANTHROPIC_API_KEY//$'\e[200~'/}; key=${key//$'\e[201~'/}; key=${key//[[:space:]]/}
    if [[ -z "$key" ]]; then
      warn "Nothing came through. Paste the key, then press Enter."
      continue
    fi
    ANTHROPIC_API_KEY=$key
    note "Got ${key:0:11}…${key: -4} (${#key} characters)."
    read -r code msg <<< "$(key_status 'x-api-key:' "$key")"
    if [[ "$code" == 200 ]]; then ok "The key works."; break; fi
    read -r bearer_code bearer_msg <<< "$(key_status 'Authorization: Bearer' "$key")"
    warn "As x-api-key: HTTP $code${msg:+ ($msg)}"
    warn "As Authorization: Bearer: HTTP $bearer_code${bearer_msg:+ ($bearer_msg)}"
    if [[ "$bearer_code" == 200 ]]; then
      warn "The key is valid, but only as a Bearer token. Claude Code may send it as x-api-key."
    elif [[ "$code" == 400 ]]; then
      warn "Most likely the key isn't scoped to a workspace. Create one that is."
    elif [[ "$code" == 401 ]]; then
      warn "The API doesn't accept this key. Check you copied all of it, or create a new one."
      continue
    fi
    confirm "Save it anyway?" && break
  done
  set_secret ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
fi
pause "Press Enter to continue"

# ── 5. README step 4: labels and the master ruleset ───────────────────────
stage "Labels and master ruleset"
say "scripts/setup-repo.sh creates the pipeline labels and a ruleset on master: changes"
say "only through a squash-merged PR with one approval and a green check."
note "Safe to re-run: it updates the labels and the ruleset in place."
warn "From then on nobody pushes straight to master, you included. Admins may bypass it inside a PR."
if confirm "Run scripts/setup-repo.sh against $REPO now?"; then
  if run ./scripts/setup-repo.sh; then
    open_url "https://github.com/$REPO/settings/rules"
    step "Open the master ruleset and check that the bypass list shows Repository admin."
    note "The script uses role id 5. If the list shows another role, fix it on that page."
  else
    warn "setup-repo.sh failed; see its output above."
  fi
fi
pause "Press Enter to continue"

# ── 6. README step 5: GitHub Pages from gh-pages ──────────────────────────
stage "GitHub Pages"
say "Deploy publishes the app to the gh-pages branch, and PR previews go under pr-preview/"
say "on it. Pages serves that branch."
if ! gh_pages_ready; then
  say "There's no gh-pages branch yet. The first Deploy run creates it."
  last=$(gh run list --workflow deploy.yml --limit 1 --json status --jq '.[0].status // ""' 2>/dev/null) || last=""
  started=no
  if [[ "$last" == queued || "$last" == in_progress ]]; then
    ok "A Deploy run is already going."; started=yes
  elif confirm "Start the Deploy workflow on $BRANCH now?"; then
    run gh workflow run deploy.yml --ref "$BRANCH"; started=yes
  fi
  if [[ "$started" == yes ]]; then
    open_url "https://github.com/$REPO/actions/workflows/deploy.yml"
    say "Waiting for gh-pages to appear (up to 10 min; Ctrl-C to stop and re-run later)"
    printf '  '
    for ((i = 0; i < 60; i++)); do
      gh_pages_ready && break
      printf '.'; sleep 10
    done
    printf '\n'
  fi
fi
if gh_pages_ready; then
  ok "The gh-pages branch exists."
  if pages_now=$(gh api "repos/{owner}/{repo}/pages" --jq '"\(.build_type) \(.source.branch) \(.source.path)"' 2>/dev/null); then
    if [[ "$pages_now" == "legacy gh-pages /" ]]; then
      ok "Pages already deploys from gh-pages / (root)."
    elif confirm "Pages is set to '$pages_now'. Switch it to gh-pages / (root)?"; then
      run gh api --method PUT "repos/{owner}/{repo}/pages" --silent \
        -f build_type=legacy -f 'source[branch]=gh-pages' -f 'source[path]=/' || pages_by_hand
    fi
  elif confirm "Turn on Pages for $REPO, deploying from gh-pages / (root)?"; then
    run gh api --method POST "repos/{owner}/{repo}/pages" --silent \
      -f build_type=legacy -f 'source[branch]=gh-pages' -f 'source[path]=/' || pages_by_hand
  else
    pages_by_hand
  fi
  if url=$(gh api "repos/{owner}/{repo}/pages" --jq .html_url 2>/dev/null); then
    ok "Pages URL: $url (the first build takes a minute or two)"
  fi
else
  warn "No gh-pages branch yet, so Pages can't be turned on. Re-run this wizard after Deploy."
fi
pause "Press Enter to continue"

# ── 7. Optional: the model the agents use ─────────────────────────────────
stage "Agent model"
say "The agent workflows pass the repo variable CLAUDE_MODEL to Claude Code's --model."
current=$(gh variable get CLAUDE_MODEL 2>/dev/null) || current=""
note "Now: ${current:-not set, so sonnet}"
say "Type an alias (sonnet, opus, haiku) or a full model ID, or press Enter to leave it."
ask CLAUDE_MODEL "Model:"
if [[ -n "$CLAUDE_MODEL" && "$CLAUDE_MODEL" != "$current" ]]; then
  set_var CLAUDE_MODEL "$CLAUDE_MODEL"
else
  ok "Model left as ${current:-sonnet}."
fi
pause "Press Enter to continue"

# ── 8. Optional: interaction limits ───────────────────────────────────────
stage "Interaction limits"
say "Anyone can comment on a public repo. AGENTS.md tells agents to ignore non-collaborators,"
say "but that's a prompt rule. An interaction limit blocks strangers' comments, issues and"
say "PRs outright, for up to 6 months at a time."
warn "Untested with this pipeline: if claude[bot] comments start failing, turn it off"
warn "in Settings → Moderation → Interaction limits."
limit=$(gh api "repos/{owner}/{repo}/interaction-limits" \
  --jq 'if .limit then "\(.limit) until \(.expires_at)" else "" end' 2>/dev/null) || limit=""
if [[ -n "$limit" ]]; then
  ok "Already limited: $limit"
elif confirm "Limit interactions on $REPO to collaborators for 6 months?"; then
  run gh api --method PUT "repos/{owner}/{repo}/interaction-limits" --silent \
    -f limit=collaborators_only -f expiry=six_months
  ok "Limited to collaborators for 6 months. Re-run this stage to renew it."
else
  ok "No interaction limit."
fi
pause "Press Enter to continue"

# ── 9. Optional: local Node and dependencies ──────────────────────────────
stage "Local: Node and npm"
say "This is for working on the app on your machine. CI uses the Node version in .nvmrc."
want=$(tr -d '[:space:]' < .nvmrc); want=${want#v}
have=$(node -v 2>/dev/null) || have=""
if [[ -z "$have" ]]; then
  warn "Node isn't installed. Install Node $want (with nvm: nvm install), then run npm ci."
  SKIPPED+=("Install Node $want locally, then npm ci && npm test")
else
  have_major=${have#v}; have_major=${have_major%%.*}
  if [[ "$have_major" == "${want%%.*}" ]]; then
    ok "Node $have matches .nvmrc ($want)."
  else
    warn "You have Node $have, but .nvmrc says $want."
    note "This wizard can't switch your shell's Node. With nvm: nvm install, then re-run."
  fi
  if confirm "Run npm ci and npm test with Node $have now?"; then
    if run npm ci && run npm test; then
      ok "Dependencies installed and tests pass."
    else
      warn "npm ci or npm test failed; see the output above."
      SKIPPED+=("Get npm ci && npm test passing locally")
    fi
  fi
fi
pause "Press Enter to continue"

# ── 10. Check what GitHub reports ─────────────────────────────────────────
stage "Check"
say "What GitHub reports for $REPO:"
verify "Repo is public" "Make $REPO public (stage 1)" is_public
verify "Secret ANTHROPIC_API_KEY is set" "Set the ANTHROPIC_API_KEY secret (stage 4)" has_secret ANTHROPIC_API_KEY
verify "Pipeline labels exist" "Create the labels: ./scripts/setup-repo.sh (stage 5)" has_labels
verify "Ruleset master exists" "Create the master ruleset: ./scripts/setup-repo.sh (stage 5)" has_ruleset
verify "Pages deploys from gh-pages" "Turn on Pages from gh-pages / (root) after the first Deploy (stage 6)" pages_ok
model=$(gh variable get CLAUDE_MODEL 2>/dev/null) || model=""
ok "Agent model: ${model:-sonnet (default)}"
say ""
say "gh can't see app installs, so check this one yourself:"
open_url "https://github.com/$REPO/settings/installations"
if confirm "Does that page list the Claude app?"; then
  ok "Claude GitHub App is installed"
else
  SKIPPED+=("Install the Claude GitHub App on $REPO (stage 2)")
fi
pause "Press Enter to continue"

# ── 11. Optional: try the pipeline (README "Try it") ──────────────────────
stage "Try it"
(( ${#SKIPPED[@]} == 0 )) || warn "Some setup is still open. Finish it first, or the first agent run will fail."
say "The pipeline starts when a collaborator gives an issue the idea label."
say "Submitting the issue starts the grill agent, which spends API tokens."
if confirm "Open a sample idea issue to submit?"; then
  open_url "https://github.com/$REPO/issues/new?title=Let%20me%20edit%20a%20to-do%27s%20title&labels=idea"
  step "Check the idea label is set, then submit the issue."
  step "Answer the agent's questions in comments. When it posts a ## Summary, reply \"ok\"."
  step "From there it runs on its own until you get a review request."
  step "Test the preview from the PR comment, then Approve or Request changes in a review."
  pause "Press Enter to finish"
fi

finish
}

run_wizard "$@"; exit
